/// <summary>
/// PricingAttribute of table <c>LogisticsPostalAddress</c> field ZipCode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeLogisticsPostalAddressZipCode extends UPSPricingAttributeLogisticsPostalAddress implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(LogisticsPostalAddress, ZipCode);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    LogisticsPostalAddress logisticsPostalAddress;

    while select logisticsPostalAddress
        group by ZipCode
    {
        if (! ret.in(logisticsPostalAddress.ZipCode))
        {
            ret.add(logisticsPostalAddress.ZipCode);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(LogisticsPostalAddress, ZipCode));
    qbr.value(queryValue(_value));
}
